package com.tuowei.erp.finance.invoice.service;
import com.tuowei.erp.finance.invoice.web.*; import com.tuowei.erp.common.web.PageResponse; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class FinanceInvoiceService {
 private final FinanceInvoiceQueryService queryService; private final FinanceInvoiceCommandService commandService;
 @Autowired public FinanceInvoiceService(FinanceInvoiceQueryService q, FinanceInvoiceCommandService c){queryService=q;commandService=c;}
 public FinanceInvoiceService(com.tuowei.erp.finance.invoice.mapper.InvoiceRegisterMapper m,InvoiceNumberService n,com.tuowei.erp.purchase.order.mapper.PurchaseOrderMapper p,com.tuowei.erp.sales.order.mapper.SalesOrderMapper s,com.tuowei.erp.common.security.AuditMetadataFactory a,com.tuowei.erp.system.attachment.service.AttachmentService x){this(new FinanceInvoiceQueryService(m,a),new FinanceInvoiceCommandService(m,n,p,s,a,x,new FinanceInvoiceQueryService(m,a)));}
 @Transactional public InvoiceResponse create(InvoiceCreateRequest r){return commandService.create(r);} @Transactional(readOnly=true) public PageResponse<InvoiceResponse> list(InvoicePageQuery q){return queryService.list(q == null ? new InvoicePageQuery() : q);} @Transactional(readOnly=true) public InvoiceResponse detail(Long id){return queryService.detail(id);} @Transactional public InvoiceResponse update(Long id,InvoiceUpdateRequest r){return commandService.update(id,r);} @Transactional public InvoiceResponse post(Long id){return commandService.post(id);} @Transactional public InvoiceResponse cancel(Long id){return commandService.cancel(id);}
}
